import java.util.Scanner;
public class JAdjacentGreater {
	public static void main(String[] args) {
		//Khutwa 1: Iqra al-raqam al-awwal allathee yadkhuluhu al-mustakhdim
		System.out.println("Adkhil al-aedad mufasilatan bimasafat aw satar jadid: ");
		Scanner scan = new Scanner(System.in); 
		double num = scan.nextDouble();
		//Khutwa 2: Iqra baqiyat al-aedad allathee yadkhuluhu al-mustakhdim wa tafaqad al-aedad al-mutajawira biltartib altasaaudi
		while (num != 0) {
			double previous = num;
			num = scan.nextDouble();	
			if ( num != 0 && num > previous ) {
				System.out.println(previous + " " + num + " fi tartib tasaaudi."); 
			}
		}
		scan.close();
	}
}
